@prefix skos: <http://www.w3.org/2004/02/skos/core#> .
@prefix sosa: <http://www.w3.org/ns/sosa/> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

<http://www.uish.org/sensors/ssn/ext#deactivationDate> a owl:DatatypeProperty ;
    rdfs:domain sosa:Platform ;
    rdfs:range xsd:dateTime ;
    skos:definition "Date and time in which the Platform has been deactivated. Since the type of this datatype property is xsd:dateTime, the date and the time are separated by a T. Then, the format is YYYY-MM-DDThh:mm:ss"@en ;
    skos:prefLabel "deactivation date"@en .

properties.xml:
@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix skos: <http://www.w3.org/2004/02/skos/core#> .
@prefix ssn: <http://www.w3.org/ns/ssn/> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

<http://www.uish.org/sensors/ssn/ext#hasAccuracy> a owl:DatatypeProperty,
        owl:FunctionalProperty ;
    rdfs:domain ssn:System ;
    rdfs:range xsd:string ;
    skos:definition "The closeness of agreement between the Result of an Observation"@en ;
    skos:prefLabel "accuracy"@en .

owl:http://www.uish.org/sensors/ssn/ext#.xml:
@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix skos: <http://www.w3.org/2004/02/skos/core#> .
@prefix sosa: <http://www.w3.org/ns/sosa/> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

<http://www.uish.org/sensors/ssn/ext#hasFrequency> a owl:DatatypeProperty,
        owl:FunctionalProperty ;
    rdfs:domain sosa:Platform ;
    rdfs:range xsd:string ;
    skos:prefLabel "frequency"@en .

@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix sosa: <http://www.w3.org/ns/sosa/> .

<http://www.uish.org/sensors/ssn/ext#has_UnitOfMeasure> a owl:ObjectProperty ;
    rdfs:subPropertyOf sosa:actsOnProperty .

@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix skos: <http://www.w3.org/2004/02/skos/core#> .
@prefix sosa: <http://www.w3.org/ns/sosa/> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

<http://www.uish.org/sensors/ssn/ext#isMobile> a owl:DatatypeProperty,
        owl:FunctionalProperty ;
    rdfs:domain sosa:Platform ;
    rdfs:range xsd:boolean ;
    skos:definition "Specifies whether the platform is installed on a moving object or not"@en ;
    skos:prefLabel "is mobile"@en .
